package dev.zomboid.density;public class Checks {static int n;static void check(boolean v){n++;if(!v)throw new AssertionError(n);}public static class Level {public java.util.List<net.minecraft.world.entity.Mob> mobs=new java.util.ArrayList<>();public boolean isClientSide(){return false;}public java.util.List<net.minecraft.world.entity.Mob> getEntitiesOfClass(Class<?> type,net.minecraft.world.phys.AABB b,java.util.function.Predicate<net.minecraft.world.entity.Mob> filter){return mobs.stream().filter(m->m.x>=b.x0()&&m.x<=b.x1()&&m.y>=b.y0()&&m.y<=b.y1()&&m.z>=b.z0()&&m.z<=b.z1()).filter(filter).toList();}}public static class Event {public Level level=new Level();public net.minecraft.world.entity.Mob mob=new net.minecraft.world.entity.Mob();public boolean saved,canceled;public Object getLevel(){return level;}public boolean loadedFromDisk(){return saved;}public Object getEntity(){return mob;}public void setCanceled(boolean c){canceled=c;}}
public static void main(String[] args){check(!Crowd.limited(false,false,"",23));check(Crowd.limited(false,false,"",24));check(Crowd.limited(false,false,"",100));check(!Crowd.limited(true,false,"",100));check(!Crowd.limited(false,true,"",100));check(!Crowd.limited(false,false,"SPAWN_EGG",100));check(!Crowd.limited(false,false,"COMMAND",100));check(Crowd.limited(false,false,"EVENT",100));Event e=new Event();for(int i=0;i<23;i++)e.level.mobs.add(new net.minecraft.world.entity.Mob());Crowd.join(e);check(!e.canceled);e.level.mobs.add(new net.minecraft.world.entity.Mob());Crowd.join(e);check(e.canceled);e.canceled=false;e.saved=true;Crowd.join(e);check(!e.canceled);e.saved=false;e.mob.reason="SPAWN_EGG";Crowd.join(e);check(!e.canceled);e.mob.reason="EVENT";for(var mob:e.level.mobs)mob.x=100;Crowd.join(e);check(!e.canceled);System.out.println("Passed "+n+" population boundary checks");}}
